import{_ as r,c as o,o as n,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Работа с логами","description":"","frontmatter":{"title":"Работа с логами"},"headers":[],"relativePath":"ru/logs/general.md","filePath":"ru/logs/general.md"}'),e={name:"ru/logs/general.md"};function g(a,t,d,h,i,l){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="работа-с-логами" tabindex="-1">Работа с логами <a class="header-anchor" href="#работа-с-логами" aria-label="Permalink to &quot;Работа с логами&quot;">​</a></h1><p>Вкладка <strong>Logs</strong> — единый хронологический журнал того, что происходит на странице: сетевые запросы, изменения props и эмиты компонентов, изменения и экшены <strong>Pinia</strong>, навигация SPA и JS-ошибки. Она помогает восстановить сценарий по шагам и передать его в виде файла.</p><p>Вкладка видна всегда, располагается после <strong>Pinia Store</strong> и записывает события одинаково в расширении и в режиме <strong>Bookmark</strong> (<a href="/qa-tools/docs/ru/standalone.html">Standalone</a>).</p><h2 id="типы-событии" tabindex="-1">Типы событий <a class="header-anchor" href="#типы-событии" aria-label="Permalink to &quot;Типы событий&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Тип</th><th>Что записывается</th></tr></thead><tbody><tr><td><strong>Send request</strong></td><td>Исходящий вызов <strong>fetch</strong> / <strong>XMLHttpRequest</strong>: URL, метод, инициатор, <strong>Params</strong>, <strong>Headers</strong> запроса, <strong>Authorization</strong>, <strong>Body</strong> запроса</td></tr><tr><td><strong>Receive response</strong></td><td>Ответ на этот вызов: статус, длительность, размер, <strong>Headers</strong> ответа, <strong>Body</strong> ответа, сетевая ошибка</td></tr><tr><td><strong>Change props</strong></td><td>Изменённые props компонента: список изменений и полные снимки <strong>Before</strong> / <strong>After</strong></td></tr><tr><td><strong>Emit</strong></td><td>Событие компонента: компонент, имя события, аргументы, тип слушателя (<strong>regular</strong> / <strong>once</strong>), цепочка родителей</td></tr><tr><td><strong>Change store</strong></td><td>Изменённый state <strong>Pinia</strong>: список изменений и полные снимки <strong>Before</strong> / <strong>After</strong>. Сюда же относятся базовые состояния стора: <strong>Store initialized</strong>, <strong>Store snapshot</strong> и <strong>Store checkpoint</strong> (см. <a href="#how-events-are-stored">Как хранятся события</a>)</td></tr><tr><td><strong>Store action</strong></td><td>Вызов экшена <strong>Pinia</strong>: аргументы, результат или ошибка, статус, длительность</td></tr><tr><td><strong>Navigation</strong></td><td>Навигация SPA: <strong>pushState</strong>, <strong>replaceState</strong>, <strong>popstate</strong>, <strong>hashchange</strong> с полями <strong>From</strong> / <strong>To</strong></td></tr><tr><td><strong>JS error</strong></td><td>Неперехваченная ошибка, необработанный reject промиса или <code>console.error</code> страницы: сообщение, источник, место, компактный стек (см. <a href="#js-errors">JS errors</a>)</td></tr></tbody></table><p>Каждый сетевой вызов даёт <strong>два</strong> события, которые ссылаются на одну общую сетевую запись. <strong>Send request</strong> показывает то, что было отправлено, <strong>Receive response</strong> — то, что пришло в ответ. Если запрос изменён на <a href="/qa-tools/docs/ru/network/traffic.html">Breakpoint</a>, оба события показывают фактически отправленные и полученные данные.</p><h2 id="верхняя-панель-управления" tabindex="-1">Верхняя панель управления <a class="header-anchor" href="#верхняя-панель-управления" aria-label="Permalink to &quot;Верхняя панель управления&quot;">​</a></h2><h3 id="поиск" tabindex="-1">Поиск <a class="header-anchor" href="#поиск" aria-label="Permalink to &quot;Поиск&quot;">​</a></h3><p>Поле поиска фильтрует таблицу. Активные критерии задаются в <strong>Options → Logs → Search Settings</strong> (см. <a href="./settings.html">Настройки логов</a>):</p><table tabindex="0"><thead><tr><th>Режим</th><th>Описание</th></tr></thead><tbody><tr><td><strong>По имени события</strong></td><td>Заголовок, компонент, стор, URL</td></tr><tr><td><strong>По ключу</strong></td><td>Ключи в данных события и пути изменений</td></tr><tr><td><strong>По значению</strong></td><td>Значения в данных события</td></tr></tbody></table><p>Для <strong>Change store</strong> и <strong>Change props</strong> поиск по ключу и значению идёт по изменённым путям и значениям; полные состояния ищутся в событиях <strong>Store initialized</strong>, <strong>Store snapshot</strong> и <strong>Store checkpoint</strong>.</p><p>Как и в других вкладках, запрос <strong>без</strong> кавычек ищет по подстроке, запрос в <strong>двойных кавычках</strong> <code>&quot;...&quot;</code> — точное совпадение. Минимальная длина запроса берётся из настроек поиска инспектора (по умолчанию <strong>2</strong> символа).</p><h3 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type&quot;">​</a></h3><p><strong>Type</strong> оставляет в таблице только выбранные типы событий. По умолчанию включены все типы. Если выключить все, таблица будет пустой и покажет подсказку снова включить типы.</p><h3 id="индикаторы-состояния" tabindex="-1">Индикаторы состояния <a class="header-anchor" href="#индикаторы-состояния" aria-label="Permalink to &quot;Индикаторы состояния&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Элемент</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>N</strong> или <strong>N/M</strong></td><td>Строк после фильтров; при активном поиске или фильтре <strong>Type</strong> <strong>M</strong> — общее число событий в буфере</td></tr><tr><td><strong>ignored</strong></td><td>Число игнорируемых групп событий. По нажатию открывается <strong>Ignored events</strong>: можно снять одно правило или все сразу (<strong>Clear all</strong>)</td></tr><tr><td><strong>Paused</strong></td><td>Запись новых событий приостановлена</td></tr></tbody></table><h3 id="управление-журналом" tabindex="-1">Управление журналом <a class="header-anchor" href="#управление-журналом" aria-label="Permalink to &quot;Управление журналом&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Элемент</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Pause</strong> / <strong>Resume</strong></td><td>Остановить и возобновить запись новых событий</td></tr><tr><td><strong>Clear</strong></td><td>Удалить все записанные события</td></tr><tr><td><strong>Export Logs</strong></td><td>Экспорт событий в <strong>HTML</strong>-отчёт (см. <a href="./export.html">Экспорт</a>)</td></tr></tbody></table><h2 id="рабочая-область" tabindex="-1">Рабочая область <a class="header-anchor" href="#рабочая-область" aria-label="Permalink to &quot;Рабочая область&quot;">​</a></h2><h3 id="таблица-событии" tabindex="-1">Таблица событий <a class="header-anchor" href="#таблица-событии" aria-label="Permalink to &quot;Таблица событий&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Колонка</th><th>Содержимое</th></tr></thead><tbody><tr><td>Чекбокс</td><td>Выбор для экспорта</td></tr><tr><td><strong>Time</strong></td><td>Время события с миллисекундами</td></tr><tr><td><strong>Type</strong></td><td>Цветной бейдж типа</td></tr><tr><td><strong>Event</strong></td><td>Заголовок и краткое описание (метод и путь, компонент и событие, стор и изменённые ключи и т.д.)</td></tr></tbody></table><p>Строки подсвечиваются по уровню: ответы <strong>4xx</strong> — предупреждение; <strong>5xx</strong>, сетевые ошибки, упавшие экшены и JS-ошибки — ошибка.</p><h3 id="выбор-для-экспорта" tabindex="-1">Выбор для экспорта <a class="header-anchor" href="#выбор-для-экспорта" aria-label="Permalink to &quot;Выбор для экспорта&quot;">​</a></h3><p>Первая колонка содержит чекбоксы — на том же месте, где во вкладках <strong>Props</strong> и <strong>Pinia</strong> находится звезда избранного.</p><table tabindex="0"><thead><tr><th>Действие</th><th>Результат</th></tr></thead><tbody><tr><td>Клик по чекбоксу</td><td>Выбрать / снять выбор строки</td></tr><tr><td><strong>Shift</strong> + клик</td><td>Выбрать диапазон от последней отмеченной строки</td></tr><tr><td><strong>Ctrl / Cmd</strong> + клик по строке</td><td>Переключить выбор строки, не открывая детализацию</td></tr><tr><td><strong>Ctrl / Cmd</strong> + <strong>A</strong> (фокус на таблице)</td><td>Выбрать все отфильтрованные строки</td></tr><tr><td>Чекбокс в шапке</td><td>Выбрать все / снять выбор</td></tr></tbody></table><p>Когда строки выбраны, кнопка показывает <strong>Export Logs (n)</strong> и экспортирует только их. Без выбора экспортируются все отфильтрованные события.</p><h3 id="детализация-события" tabindex="-1">Детализация события <a class="header-anchor" href="#детализация-события" aria-label="Permalink to &quot;Детализация события&quot;">​</a></h3><p>Клик по строке открывает детализацию справа. Оформление повторяет <strong>Network</strong>: вкладки, таблицы «имя / значение» и блоки <strong>JSON</strong> в выбранном <a href="/qa-tools/docs/ru/options/json_mode.html">режиме JSON</a>.</p><table tabindex="0"><thead><tr><th>Тип</th><th>Вкладки</th></tr></thead><tbody><tr><td><strong>Send request</strong></td><td><strong>Overview</strong>, <strong>Params (n)</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Receive response</strong></td><td><strong>Overview</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Change props</strong>, <strong>Change store</strong></td><td><strong>Changes (n)</strong>, <strong>Before</strong>, <strong>After</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Store initialized</strong>, <strong>Store snapshot</strong>, <strong>Store checkpoint</strong></td><td><strong>Overview</strong>, <strong>State</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Store action</strong></td><td><strong>Overview</strong>, <strong>Arguments</strong>, <strong>Result</strong> / <strong>Error</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Emit</strong></td><td><strong>Arguments (n)</strong>, <strong>Overview</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Navigation</strong>, <strong>JS error</strong></td><td><strong>Overview</strong>, <strong>Stack</strong> (для ошибок), <strong>Raw</strong></td></tr></tbody></table><p><strong>Changes</strong> показывает разницу по путям: добавленные, удалённые и изменённые значения со старым и новым значением. Очень большие списки изменений обрезаются; полное состояние остаётся на вкладках <strong>Before</strong> / <strong>After</strong>.</p><p><strong>Before</strong> / <strong>After</strong> изменения стора восстанавливаются из базового состояния стора и изменений после него. Если это невозможно (более ранних событий стора в журнале уже нет), вкладка сообщает об этом, а <strong>Changes</strong> по-прежнему показывает изменённые значения; значение, которое нельзя восстановить, отображается как <em>not available</em>.</p><p><strong>Raw</strong> показывает событие со всеми восстановленными полями.</p><p>Если сетевое тело было больше заданного размера события, на вкладке <strong>Body</strong> показывается предупреждение с исходным размером.</p><h3 id="деиствия-с-событием" tabindex="-1">Действия с событием <a class="header-anchor" href="#деиствия-с-событием" aria-label="Permalink to &quot;Действия с событием&quot;">​</a></h3><p>Действия доступны в меню <strong>⋮</strong> в шапке детализации и в контекстном меню строки (правая кнопка мыши или <strong>⋮</strong> в строке):</p><table tabindex="0"><thead><tr><th>Действие</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Export event</strong></td><td>Экспорт одного события. Для сетевых событий пункт называется <strong>Export request &amp; response</strong>: оба события запроса попадают в один файл</td></tr><tr><td><strong>Copy cURL</strong></td><td>Скопировать запрос как команду cURL (доступно и для <strong>Receive response</strong>: оба события используют общие данные запроса)</td></tr><tr><td><strong>Open request event</strong> / <strong>Open response event</strong></td><td>Перейти к парному сетевому событию</td></tr><tr><td><strong>Ignore</strong></td><td>Перестать записывать эту группу событий</td></tr></tbody></table><p><strong>Ignore</strong> работает по группам: один и тот же запрос (метод и путь), один и тот же компонент, один и тот же стор и т.д. События игнорируемых групп не записываются вовсе; вернуть запись можно в <strong>Options → Logs → Ignore list</strong>.</p><h2 id="принципы-работы" tabindex="-1">Принципы работы <a class="header-anchor" href="#принципы-работы" aria-label="Permalink to &quot;Принципы работы&quot;">​</a></h2><h3 id="когда-начинается-запись" tabindex="-1">Когда начинается запись <a class="header-anchor" href="#когда-начинается-запись" aria-label="Permalink to &quot;Когда начинается запись&quot;">​</a></h3><p>Запись начинается вместе с остальными модулями Vue Inspector в контексте вкладки. События хранятся на странице, поэтому история доступна, даже если открыть <strong>Logs</strong> позже, без перезагрузки страницы.</p><h3 id="how-events-are-stored" tabindex="-1">Как хранятся события <a class="header-anchor" href="#how-events-are-stored" aria-label="Permalink to &quot;Как хранятся события {#how-events-are-stored}&quot;">​</a></h3><p>События хранят только исходные данные; заголовки, описания и полные состояния вычисляются при показе события.</p><ul><li><strong>Pinia.</strong> Если стор создаётся во время записи, событие <strong>Store initialized</strong> фиксирует его полное состояние. Если запись начинается на уже существующем сторе, событие <strong>Store snapshot</strong> фиксирует его текущее состояние. Дальше каждое событие <strong>Change store</strong> хранит только изменения. <strong>Before</strong> / <strong>After</strong> восстанавливаются из базового состояния и изменений до события. Переключение вкладок Inspector новых снимков не создаёт. Новый снимок записывается после <strong>Clear</strong> и после изменения настроек маскирования. Записанное состояние разделено так же, как на вкладке <strong>Pinia Store</strong>: в <code>state</code> — объявленный state, в <code>getters</code> — геттеры и данные, которые стор хранит вне объявленного state (например, поля, присвоенные в actions options-стора с пустым <code>state()</code>). Изменения обеих частей отслеживаются, поэтому пути изменений начинаются с <code>state.</code> или <code>getters.</code>.</li><li><strong>Network.</strong> <strong>Send request</strong> и <strong>Receive response</strong> ссылаются на одну общую сетевую запись. Одинаковые тела запросов и ответов (например, у опрашиваемого эндпоинта) хранятся один раз.</li><li><strong>Общие снимки.</strong> Одинаковые значения внутри любого события — пропсы, состояние стора, аргументы и результаты actions, аргументы emit, ошибки, навигация — хранятся один раз. Каждая следующая копия — ссылка на этот снимок. Вкладка Logs и HTML-отчёт восстанавливают полное значение, поэтому на экране те же данные, которые были записаны.</li></ul><h3 id="лимиты" tabindex="-1">Лимиты <a class="header-anchor" href="#лимиты" aria-label="Permalink to &quot;Лимиты&quot;">​</a></h3><p>Стабильность длительных сессий обеспечивает общий бюджет памяти: при его достижении удаляются самые старые события. По умолчанию события хранятся целиком; максимальный размер события можно включить. Группы событий можно отключить полностью. Значения по умолчанию и настройки описаны в разделе <a href="./settings.html">Настройки логов</a>.</p><p>Старые события <strong>Change store</strong> не просто удаляются: они сжимаются в <strong>Store checkpoint</strong> с состоянием стора на этот момент, и история принимает вид <em>начальное состояние → checkpoint → последние изменения</em>. Начальное состояние сохраняется, каждое оставшееся изменение по-прежнему восстанавливается, а сжатые изменения больше не показываются по отдельности (checkpoint показывает, сколько изменений в него вошло).</p><h3 id="js-errors" tabindex="-1">JS errors <a class="header-anchor" href="#js-errors" aria-label="Permalink to &quot;JS errors {#js-errors}&quot;">​</a></h3><p>События <strong>JS error</strong> приходят из трёх источников, они показаны в <strong>Overview</strong> как <strong>Source</strong>: <strong>Uncaught error</strong>, <strong>Unhandled rejection</strong> и <strong>console.error</strong>.</p><ul><li><strong>Только инспектируемая страница.</strong> Принадлежность ошибки странице определяется по её источнику (вызывающему коду в стеке), а не по тексту. Сообщения и ошибки самого Vue Inspector и других расширений браузера не записываются. Это касается и внутренних сообщений Vue Inspector о неудачных запросах <strong>fetch</strong> / <strong>XHR</strong>: такой запрос уже есть как событие <strong>Network</strong>. Собственный <code>console.error</code> приложения о неудачном запросе сохраняется.</li><li><strong>console.error.</strong> Сообщение собирается так же, как в консоли браузера (<code>%s</code>, <code>%d</code>, <code>%o</code> и подобные подставляются, объекты показываются кратким превью); аргументы-объекты сохраняются в <strong>Raw</strong>. <strong>Location</strong> указывает на строку приложения, вызвавшую <code>console.error</code>, или на верхний кадр переданной ошибки. Больше 50 сообщений в секунду не записываются; следующее событие показывает, сколько пропущено (<strong>Suppressed</strong>).</li><li><strong>Компактный стек.</strong> Сохраняются сообщение и 10 верхних кадров — место, где возникла ошибка. Усечённый стек заканчивается строкой <em>… N more frames (stack truncated)</em>, а <strong>Overview</strong> показывает <strong>Stack: Truncated</strong> с числом сохранённых кадров.</li><li>Сообщения <strong>WebSocket</strong> не захватываются.</li></ul><p>Ошибки инспектируемой страницы остаются в консоли страницы и во вкладке <strong>Logs</strong>. В список ошибок расширения (<code>chrome://extensions</code>) они не попадают: там только сбои самого Vue Inspector. Во время записи <code>console.error</code> страницы проходит через небольшой мост на стороне страницы, поэтому консоль браузера может указать этот мост как источник строки. Само сообщение и его стек не меняются.</p><h3 id="маскирование-данных" tabindex="-1">Маскирование данных <a class="header-anchor" href="#маскирование-данных" aria-label="Permalink to &quot;Маскирование данных&quot;">​</a></h3><p>Чувствительные данные маскируются <strong>в момент записи события</strong>, поэтому не попадают ни в интерфейс, ни в экспорт: пароли, токены, cookies, заголовки авторизации, номера карт и похожие ключи, а также <strong>JWT</strong>, учётные данные <strong>Bearer</strong> / <strong>Basic</strong> и номера карт внутри любого текста.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./export.html">Экспорт</a></li><li><a href="./settings.html">Настройки логов</a></li><li><a href="/qa-tools/docs/ru/network/general.html">Работа с запросами</a></li></ul>',54)])])}const u=r(e,[["render",g]]);export{p as __pageData,u as default};
